func:
// 1. Extrair o valor calculado pelo ESP32
var volumeESP = msg.payload.volume;

// 2. Forçar formato decimal (Float) para evitar conflitos no InfluxDB
var decibeisFinais = parseFloat(volumeESP);

// 3. Recuperar o tráfego da API de Mapas (Ex. TomTom)
var congestionamentoVial = context.global.get('indice_trafico') || 0;

// 4. Formatar o payload para o Banco de Dados
// Nota: As chaves do JSON foram mantidas para não quebrar a consulta no Grafana
msg.payload = {
    decibelios_reales: decibeisFinais,
    congestio_api: congestionamentoVial
};

// 5. Etiquetas (Tags) anonimizadas para segurança
msg.tags = {
    estudante: "usuario_github",
    sensor: "sparkfun_generico"
};

return msg;
